// Offline source-contour refinement. The sprite is never modified; this only
// proposes pixel coverage for the anatomy polygons generated by the A helper.
const templeStarts = [218,212,230,218,207,213,211,221,223,228,219,227,235,226,227,228];
const templeEnds = [255,253,265,245,240,255,232,253,252,245,255,260,270,260,265,268];
function restoreRows(face, anchors) {
  for (let k = 0; k + 1 < anchors.length; k++) {
    const [y0, l0, r0] = anchors[k], [y1, l1, r1] = anchors[k + 1];
    for (let y = y0; y <= y1; y++) {
      const t = (y - y0) / (y1 - y0), left = Math.round(l0 + (l1 - l0) * t), right = Math.round(r0 + (r1 - r0) * t);
      for (let x = left; x <= right; x++) face[y * 512 + x] = 1;
    }
  }
}
function restorePolygon(face, polygon) {
  const minX = Math.min(...polygon.map(([x]) => x)), maxX = Math.max(...polygon.map(([x]) => x));
  const minY = Math.min(...polygon.map(([, y]) => y)), maxY = Math.max(...polygon.map(([, y]) => y));
  for (let y = minY; y <= maxY; y++) for (let x = minX; x <= maxX; x++) {
    let inside = false;
    for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
      const [a, b] = polygon[i], [c, d] = polygon[j];
      if ((b > y + .5) !== (d > y + .5) && x + .5 < (c - a) * (y + .5 - b) / (d - b) + a) inside = !inside;
    }
    if (inside) face[y * 512 + x] = 1;
  }
}

export function refineFullFaceA(character, source, input, hsl) {
  const face = Uint8Array.from(input);
  const light = (x, y) => hsl[y * 512 + x][2];
  // Locate the peach cheek outside the eyelash, then its adjacent source ink.
  // Never use the darkest eye pixel as the cheek boundary: on several looks
  // a narrow strip of real skin lies between that eyelash and the outer ink.
  for (let y = templeStarts[character]; y < templeEnds[character]; y++) {
    let right = 0;
    for (let x = 150; x < 430; x++) if (input[y * 512 + x]) right = x;
    if (!right) continue;
    let peach = -1;
    for (let x = right - 12; x <= right; x++) {
      const p = y * 512 + x, i = p * 4, [h, s, l] = hsl[p];
      const minimum = Math.min(source[i], source[i + 1], source[i + 2]);
      const maximum = Math.max(source[i], source[i + 1], source[i + 2]);
      if ((source[i] > 190 && source[i + 2] > 100 && h < 35 && s > .15 && l > .55)
        || (minimum >= 210 && maximum - minimum < 45)) peach = x;
    }
    let edge = right;
    if (peach >= 0) {
      let value = Infinity;
      for (let x = peach; x <= Math.min(right + 4, peach + 4); x++) {
        const l = light(x, y);
        if (l < value) { edge = x; value = l; }
      }
    }
    for (let x = right - 12; x <= right + 4; x++) if (x > edge) face[y * 512 + x] = 0; else if (x >= right) face[y * 512 + x] = 1;
  }
  // Inspect only the narrow outside edge of the forehead/bangs. Golden strand
  // pixels have a much larger red/blue separation than pale cheek highlights.
  // These are source-color proposals, checked against enlarged source proofs.
  const boundary = new Uint8Array(512 * 512);
  for (let y = 100; y < templeEnds[character]; y++) for (let x = 100; x < 430; x++) {
    const p = y * 512 + x;
    if (!input[p]) continue;
    let outside = false;
    for (let dy = -3; dy <= 3 && !outside; dy++) for (let dx = -3; dx <= 3; dx++) {
      if (!input[(y + dy) * 512 + x + dx]) { outside = true; break; }
    }
    if (outside) boundary[p] = 1;
  }
  for (let p = 0; p < boundary.length; p++) {
    if (!boundary[p]) continue;
    const [h, s, l] = hsl[p], i = p * 4;
    if (h >= 37 && h < 70 && s > .30 && l > .40 && source[i] - source[i + 2] > 100) face[p] = 0;
  }
  if (character === 3) {
    // Outer eyelash and the separate cheek stroke measured on each source row.
    // Row230's true stroke361 must not collapse onto the black eyelash357.
    const right = [367,367,368,368,368,368,364,364,363,363,364,364,361,362,360,360,357,357,357,356,356,356,355,355,355,354,352];
    for (let row = 0; row < right.length; row++) for (let x = 346; x < 380; x++) face[(218 + row) * 512 + x] = Number(x <= right[row]);
  }
  if (character === 4) {
    // Measured outer eyelash followed by the separate brown cheek stroke.
    // In particular row217's pale skin at350..351 is outside the black eye
    // contour at348; the actual cheek boundary is353, not the darker eyelash.
    const right = [358,358,358,360,360,360,359,357,357,355,355,355,355,354,354,354,354,353,352,352,352,351,351,351,349,349,349,349,348,348,347,347,347,347,346,345,345,345,345,345];
    for (let row = 0; row < right.length; row++) for (let x = 335; x < 370; x++) face[(200 + row) * 512 + x] = Number(x <= right[row]);
  }
  if (character === 2) {
    // The shaded triangular ear behind the front curl was absent from the
    // original anatomy, apart from its pale lower tip. Follow its source rim.
    restorePolygon(face, [[174,253],[175,257],[174,262],[174,268],[175,273],[175,280],[173,284],[171,283],[168,281],[166,280],[164,278],[162,275],[163,272],[165,269],[166,265],[168,262],[171,258]]);
  }
  if (character === 5) {
    // Forehead and eyebrow between the left sweep and central bang. The old
    // color-derived outline made visible bites into this warm skin wedge.
    restoreRows(face, [[179,221,247],[181,220,247],[183,218,246],[185,217,246],[187,215,246],[189,213,245],[191,211,244],[193,210,244],[195,209,244],[197,207,243],[199,205,242],[201,204,242]]);
  }
  if (character === 13) {
    // This skin wedge contains yellow illumination (hue37..40); it remains
    // anatomy despite matching the source hair palette numerically.
    restoreRows(face, [[187,229,252],[189,223,252],[191,222,252],[193,221,252],[195,221,252],[197,218,252],[199,218,252],[201,216,252],[203,215,252],[205,214,250],[207,213,250],[209,210,250]]);
  }
  // Source-confirmed end pixels of the small curls crossing the cheek, and
  // the single narrow strand crossing look9's forehead/eyebrow.
  const strandTips = {
    8: [[213,258],[214,258],[213,260],[214,260],[215,260]],
    9: [[201,186],[202,186],[202,187]],
    11: [[265,264],[266,265],[267,266],[267,267],[268,267],[273,271],[277,273],[278,273],[279,273],[282,274],[283,274]],
  };
  for (const [x, y] of strandTips[character] || []) face[y * 512 + x] = 0;
  return face;
}
